// Independent logic audit for Hollowbough. One numbered rule = one assertion block against the real engine.
//   node logic-test.js          run all rules, print one line per failure: "FAIL rule N: expected X, got Y"
//   node logic-test.js --md     print the numbered rule list (this is the source of RULES-CHECKLIST.md)
// Written from the published rulebook, NOT from the builders' tests. Only state-building helpers are shared (game/tlib.js).
const path = require('path');
const T = require(path.join(__dirname, 'game', 'tlib'));
const HB = T.HB, D = T.D, X = HB._;
const RULES = [];
let SECTION = '';
const sec = s => { SECTION = s; };
const R = (text, fn) => { RULES.push({ n: RULES.length + 1, sec: SECTION, text, fn }); };
const NA = (text) => R(text, null);
class Miss extends Error { }
const eq = (got, exp, what) => { if (JSON.stringify(got) !== JSON.stringify(exp)) throw new Miss((what ? what + ': ' : '') + 'expected ' + JSON.stringify(exp) + ', got ' + JSON.stringify(got)); };
const yes = (c, what) => { if (!c) throw new Miss('expected ' + what + ', got false'); };
const no = (c, what) => { if (c) throw new Miss('expected NOT ' + what + ', got it'); };

// ---------- state helpers ----------
const mk = (np, seed) => { const G = T.game(np || 2, { seed: seed || 3 }); for (let s = 0; s < G.np; s++) T.hand(G, s, []); return G; };
const P = (G, s) => G.players[s || 0];
const FI = k => D.forest.findIndex(f => f.key === 'forest_' + k);
const setForest = (G, keys) => { G.forest = keys.map(FI); };
const FOR3 = ['bumper_bramble', 'mixed_glade', 'sapwell_copse', 'berry_thicket'];
const SI = k => D.specialEvents.findIndex(e => e.key === 'sev_' + k);
const setSev = (G, keys) => { G.sev = keys.map(k => ({ k: SI(k), o: -1, tuck: [], hid: false, stock: { twig: 0, resin: 0, pebble: 0, berry: 0 } })); };
const bkey = i => D.basic[i].key.replace('basic_', '');
const wk = (G, s, pred) => { T.cur(G, s); return T.act(G, s, m => m.type === 'worker' && pred(m)); };
const wBasic = (G, s, k) => wk(G, s, m => m.k === 'basic' && bkey(m.i) === k);
const wForest = (G, s, i) => wk(G, s, m => m.k === 'forest' && m.i === i);
const wDest = (G, s, key, owner) => wk(G, s, m => m.k === 'dest' && HB.cardKey(m.c) === key && (owner == null || m.o === owner));
const canW = (G, s, pred) => { T.cur(G, s); return HB.moves(G, s).some(m => m.type === 'worker' && pred(m)); };
const canBasic = (G, s, k) => canW(G, s, m => m.k === 'basic' && bkey(m.i) === k);
const play = (G, s, id, how) => { T.cur(G, s); return T.act(G, s, m => m.type === 'play' && m.card === id && (!how || m.how === how)); };
const canPlay = (G, s, id, how) => { T.cur(G, s); return HB.moves(G, s).some(m => m.type === 'play' && m.card === id && (!how || m.how === how)); };
const chL = (G, re) => T.q(G, m => m.type === 'choose' && re.test(m.label));
const chC = (G, id) => T.q(G, m => m.type === 'choose' && m.card === id);
const chR = (G, r) => T.q(G, m => m.type === 'choose' && m.res === r);
const pend = G => G.q ? G.q.kind : null;
const stop = G => chL(G, /^(Done|Stop|Do not|Play none|Play neither|Place none)/);
const city = (G, s, keys) => T.city(G, s, keys);
const hand = (G, s, keys) => T.hand(G, s, keys);
const res = (G, s, o) => T.res(G, s, o);
const E = (G, s, k) => T.entry(G, s, k);
const inCity = (G, s, k) => !!E(G, s, k);
const score = (G, s) => HB.score(G, s || 0);
const rs = (G, s) => { const r = P(G, s).res; return { twig: r.twig, resin: r.resin, pebble: r.pebble, berry: r.berry }; };
const R0 = (o) => Object.assign({ twig: 0, resin: 0, pebble: 0, berry: 0 }, o || {});
const rsum = o => o.twig + o.resin + o.pebble + o.berry;
const key = id => HB.cardKey(id);
const FILL = n => { const a = []; const pool = ['farm', 'farm', 'farm', 'farm', 'farm', 'farm', 'farm', 'farm', 'mine', 'mine', 'mine', 'resin_refinery', 'resin_refinery', 'resin_refinery', 'twig_barge']; for (let i = 0; i < n; i++) a.push(pool[i]); return a; };
const J8 = ['twig_barge', 'twig_barge', 'twig_barge', 'general_store', 'general_store', 'general_store', 'resin_refinery', 'resin_refinery'];
const prepare = (G, s) => { T.cur(G, s); return T.act(G, s, m => m.type === 'prepare'); };
const passMv = (G, s) => { T.cur(G, s); return T.act(G, s, m => m.type === 'pass'); };
const withFreeWorkersUsed = (G, s) => { const p = P(G, s); while (p.workers - p.dep.length > 0) p.dep.push({ k: 'basic', i: 0 }); };
const meadowSet = (G, slot, key) => T.meadow(G, slot, key);
const bonusOf = (G, s, k) => { const e = E(G, s, k); const d = score(G, s).detail.find(x => x.card === e.id); return d ? d.bonus : 0; };
const costOf = k => D.cards.find(c => c.key === k).cost;

// ============================================================ RULES
sec('A. Components and setup');
R('The deck has 128 cards: 63 Critters and 65 Constructions.', () => { let c = 0, k = 0; for (let i = 0; i < 128; i++) HB.cardOf(i).kind === 'critter' ? c++ : k++; eq([HB.NCARDS, c, k], [128, 63, 65]); });
R('There are 48 distinct cards; copies by colour: Production 52, Governance 21, Traveler 19, Prosperity 18, Destination 18.', () => { const n = {}; for (let i = 0; i < 128; i++) { const c = HB.cardOf(i).color; n[c] = (n[c] || 0) + 1; } eq([D.cards.length, n.green, n.blue, n.tan, n.purple, n.red], [48, 52, 21, 19, 18, 18]); });
R('Copies per card match the rulebook (Farm 8; Husband/Wife 4; Wanderer, Teacher, Peddler, Miner Mole, Chip Sweep, Barge Toad, Woodcarver 3; uniques 2 or 3).', () => { const exp = { farm: 8, husband: 4, wife: 4, wanderer: 3, teacher: 3, peddler: 3, miner_mole: 3, chip_sweep: 3, barge_toad: 3, woodcarver: 3, postal_pigeon: 3, historian: 3, shopkeeper: 3, innkeeper: 3, queen: 2, king: 2, castle: 2, palace: 2, ever_tree: 2, crane: 3, clock_tower: 3, fair_grounds: 3, mine: 3, resin_refinery: 3, twig_barge: 3, general_store: 3, storehouse: 3, inn: 3, post_office: 3, ruins: 3 }; const bad = []; for (const k in exp) if (D.cards.find(c => c.key === k).copies !== exp[k]) bad.push(k + '=' + D.cards.find(c => c.key === k).copies + '(want ' + exp[k] + ')'); eq(bad, []); });
R('Printed base points: Fool -2, Queen 4, King 4, Doctor 4, Castle 4, Palace 4, Ever Tree 5, Theater 3, Fair Grounds 3, University 3, Wife 2, Husband 2, Farm 1, Mine 2, Ruins 0, Cemetery 0, Dungeon 0, Clock Tower 0, Bard 0, Monk 0.', () => { const exp = { fool: -2, queen: 4, king: 4, doctor: 4, castle: 4, palace: 4, ever_tree: 5, theater: 3, fair_grounds: 3, university: 3, wife: 2, husband: 2, farm: 1, mine: 2, ruins: 0, cemetery: 0, dungeon: 0, clock_tower: 0, bard: 0, monk: 0 }; const bad = []; for (const k in exp) { const c = D.cards.find(x => x.key === k); if (c.pts !== exp[k]) bad.push(k + '=' + c.pts); } eq(bad, []); });
R('Card costs: Farm 2 twig+1 resin; Mine 1/1/1; Castle 2 twig,3 resin,3 pebble; Ever Tree 3/3/3; Ruins free; Cemetery 2 pebble; Crane 1 pebble; Husband 3 berries (independent card wiki: cost 3, 2 pts); Wife 2 berries; Queen 5 berries; King 6 berries; Monk 1 berry; Innkeeper 1 berry.', () => { eq([costOf('farm'), costOf('mine'), costOf('castle'), costOf('ever_tree'), costOf('ruins'), costOf('cemetery'), costOf('crane'), costOf('husband'), costOf('wife'), costOf('queen'), costOf('king'), costOf('monk'), costOf('innkeeper')], [{ twig: 2, resin: 1 }, { twig: 1, resin: 1, pebble: 1 }, { twig: 2, resin: 3, pebble: 3 }, { twig: 3, resin: 3, pebble: 3 }, {}, { pebble: 2 }, { pebble: 1 }, { berry: 3 }, { berry: 2 }, { berry: 5 }, { berry: 6 }, { berry: 1 }, { berry: 1 }]); });
R('Setup: each player starts with 2 workers, no resources, season Winter; 8 cards face-up in the Meadow.', () => { for (let np = 2; np <= 4; np++) { const G = T.game(np); eq(G.meadow.filter(x => x >= 0).length, 8, 'meadow'); for (const p of G.players) { eq(p.workers, 2); eq(p.season, 0); eq(rsum(p.res), 0); eq(p.dep.length, 0); } } });
R('Starting hands: seat 1 draws 5, seat 2 draws 6, seat 3 draws 7, seat 4 draws 8.', () => { const G = T.game(4); eq(G.players.map(p => p.hand.length), [5, 6, 7, 8]); });
R('Forest: 3 Forest cards in a 2-player game, 4 in 3- and 4-player games, all different.', () => { eq([T.game(2).forest.length, T.game(3).forest.length, T.game(4).forest.length], [3, 4, 4]); for (let s = 1; s < 15; s++) { const f = T.game(4, { seed: s }).forest; eq(new Set(f).size, 4); } });
R('Events: the 4 basic events are always in play; 4 different special events are drawn from the 16.', () => { eq(D.specialEvents.length, 16); for (let s = 1; s < 15; s++) { const G = T.game(2, { seed: s }); eq(G.bev.length, 4); eq(new Set(G.sev.map(e => e.k)).size, 4); } });
R('Board: 8 basic locations, 11 Forest locations, 4 basic events (3 pts each), 4 Journey spots worth 5/4/3/2, one Haven.', () => { eq([D.basic.length, D.forest.length, D.basicEvents.length, D.basicEvents.map(e => e.pts), D.journey.map(j => j.points)], [8, 11, 4, [3, 3, 3, 3], [5, 4, 3, 2]]); });
R('Basic events: 4 Production (green), 3 Destination (red), 3 Governance (blue), 3 Traveler (tan).', () => { eq(D.basicEvents.map(e => e.need), [{ production: 4 }, { destination: 3 }, { governance: 3 }, { traveler: 3 }]); });
R('Seat 1 plays first; play proceeds clockwise (seat order) and wraps.', () => { const G = mk(3); eq(HB.actor(G), 0); wBasic(G, 0, 'berry_patch'); eq(HB.actor(G), 1); wBasic(G, 1, 'berry_patch'); eq(HB.actor(G), 2); wBasic(G, 2, 'berry_patch'); eq(HB.actor(G), 0); });
R('Hand limit is 8: drawing stops at 8 cards (resources/other effects of the same action still happen).', () => { const G = mk(2); hand(G, 0, J8); wBasic(G, 0, 'dewberry_nook'); eq([P(G).hand.length, P(G).res.berry], [8, 1]); });
R('City limit is 15 cards: a 16th card cannot be played.', () => { const G = mk(2); city(G, 0, FILL(15)); const [id] = hand(G, 0, ['twig_barge']); res(G, 0, { twig: 1, pebble: 1 }); eq(canPlay(G, 0, id), false); });
R('Resources are unlimited (no supply cap on any pile).', () => { const G = mk(2); res(G, 0, { berry: 60 }); wBasic(G, 0, 'berry_patch'); eq(P(G).res.berry, 61); });
NA('Component art, box contents, tokens as physical pieces (UI only).');

sec('B. Turn structure');
R('A turn is exactly one action: place a worker, play a card, or prepare for season; then the turn passes to the next player.', () => { const G = mk(2); wBasic(G, 0, 'pebble_bank'); eq(G.cur, 1); const [id] = hand(G, 1, ['mine']); res(G, 1, { twig: 1, resin: 1, pebble: 1 }); play(G, 1, id); eq(G.cur, 0); });
R('You may place a worker only if you have an unplaced worker.', () => { const G = mk(2); wBasic(G, 0, 'pebble_bank'); wBasic(G, 1, 'berry_patch'); wBasic(G, 0, 'resin_pool'); wBasic(G, 1, 'twig_heap'); T.cur(G, 0); eq(HB.moves(G, 0).filter(m => m.type === 'worker').length, 0); });
R('Prepare for season is offered only when all your workers are placed.', () => { const G = mk(2); eq(HB.moves(G, 0).some(m => m.type === 'prepare'), false); withFreeWorkersUsed(G, 0); eq(HB.moves(G, 0).some(m => m.type === 'prepare'), true); });
R('Passing: a passed player takes no more turns; the game ends when every player has passed.', () => { const G = mk(3); passMv(G, 0); eq(HB.actor(G), 1); passMv(G, 1); eq(HB.actor(G), 2); wBasic(G, 2, 'berry_patch'); eq(HB.actor(G), 2, 'only seat 3 left'); passMv(G, 2); eq(G.phase, 'over'); });
R('A passed player cannot be given resources: Monk with the only rival passed gives nothing and asks nothing.', () => { const G = mk(2); passMv(G, 1); const [m] = hand(G, 0, ['monk']); res(G, 0, { berry: 3 }); play(G, 0, m); eq([pend(G), P(G).pts, P(G, 1).res.berry], [null, 0, 0]); });
R('A passed player cannot be given cards: Teacher keeps one card and discards the other when every rival has passed.', () => { const G = mk(2); passMv(G, 1); const [t] = hand(G, 0, ['teacher']); res(G, 0, { berry: 2 }); const d0 = G.discard.length, h1 = P(G, 1).hand.length; play(G, 0, t); chL(G, /Keep/); eq([P(G, 1).hand.length - h1, G.discard.length - d0], [0, 1]); });
R('Playing a card from the Meadow replaces it immediately from the deck.', () => { const G = mk(2); const id = meadowSet(G, 3, 'farm'); res(G, 0, { twig: 2, resin: 1 }); play(G, 0, id); yes(G.meadow[3] >= 0 && G.meadow[3] !== id, 'slot 3 refilled'); eq(G.meadow.filter(x => x >= 0).length, 8); });
R('Deck empty: the discard pile is shuffled into a new deck.', () => { const G = mk(2); G.discard = G.discard.concat(G.deck); G.deck = []; wBasic(G, 0, 'dewberry_nook'); eq(P(G).hand.length, 1); eq(G.deck.length > 0, true); T.inv(G); });

sec('C. Basic locations');
const BASIC = [['berry_patch', { berry: 1 }, 0, 0, true], ['dewberry_nook', { berry: 1 }, 1, 0, false], ['amber_weep', { resin: 1 }, 1, 0, true], ['pebble_bank', { pebble: 1 }, 0, 0, false], ['twig_heap', { twig: 3 }, 0, 0, false], ['gossip_glade', {}, 2, 1, true], ['resin_pool', { resin: 2 }, 0, 0, false], ['kindling_glen', { twig: 2 }, 1, 0, true]];
for (const [k, g, dr, pt, sh] of BASIC) {
  R('Basic location ' + k + ': gives ' + JSON.stringify(g) + ' + ' + dr + ' card(s) + ' + pt + ' point token(s); ' + (sh ? 'shared' : 'exclusive') + '.', () => {
    const G = mk(3); wBasic(G, 0, k);
    eq([rs(G, 0), P(G).hand.length, P(G).pts], [R0(g), dr, pt]);
    eq(canBasic(G, 1, k), sh);
    if (sh) { wBasic(G, 1, k); eq(rs(G, 1), R0(g)); eq(canBasic(G, 0, k), P(G).workers - P(G).dep.length > 0, 'same player may stack on a shared spot'); }
  });
}

sec('D. Forest locations');
const FEFF = [
  ['berry_thicket', G => { wForest(G, 0, 0); eq([rs(G), P(G).hand.length], [R0({ berry: 2 }), 1]); }],
  ['foragers_crossing', G => { wForest(G, 0, 0); chR(G, 'twig'); chR(G, 'pebble'); eq(rs(G), R0({ twig: 1, pebble: 1 })); eq(pend(G), null); }],
  ['rummage_hollow', G => { hand(G, 0, ['farm', 'mine', 'castle']); wForest(G, 0, 0); chL(G, /Discard/); chL(G, /Discard/); stop(G); eq(P(G).hand.length, 1 + 4); }],
  ['echoing_meadow', G => { wForest(G, 0, 0); chL(G, /Copy/); eq(P(G).hand.length, 1); eq(rsum(P(G).res) > 0, true, 'copied a basic location'); }],
  ['quarry_burrow', G => { wForest(G, 0, 0); eq([rs(G), P(G).hand.length], [R0({ pebble: 1 }), 3]); }],
  ['mixed_glade', G => { wForest(G, 0, 0); eq(rs(G), R0({ twig: 1, resin: 1, berry: 1 })); }],
  ['bumper_bramble', G => { wForest(G, 0, 0); eq(rs(G), R0({ berry: 3 })); }],
  ['sapwell_copse', G => { wForest(G, 0, 0); eq(rs(G), R0({ resin: 2, twig: 1 })); }],
  ['postbag_clearing', G => { wForest(G, 0, 0); chR(G, 'resin'); eq([rs(G), P(G).hand.length], [R0({ resin: 1 }), 2]); }],
  ['barter_stump', G => { hand(G, 0, ['farm', 'mine', 'castle', 'palace']); wForest(G, 0, 0); chL(G, /Discard/); chL(G, /Discard/); stop(G); chR(G, 'pebble'); chR(G, 'pebble'); eq([rs(G), P(G).hand.length], [R0({ pebble: 2 }), 2]); }],
];
for (const [k, fn] of FEFF) R('Forest ' + k + ': ' + D.forest[FI(k)].text, () => { const G = mk(2); setForest(G, [k, 'bumper_bramble', 'mixed_glade']); fn(G); });
R('Forest rummage_hollow: discard limit is only the hand; drawing respects the 8-card limit.', () => { const G = mk(2); setForest(G, ['rummage_hollow', 'bumper_bramble', 'mixed_glade']); hand(G, 0, J8); wForest(G, 0, 0); for (let i = 0; i < 6; i++) chL(G, /Discard/); stop(G); eq(P(G).hand.length, 2 + 8 > 8 ? 8 : 10); });
R('Forest barter_stump: at most 3 cards may be discarded (1 resource each).', () => { const G = mk(2); setForest(G, ['barter_stump', 'bumper_bramble', 'mixed_glade']); hand(G, 0, J8); wForest(G, 0, 0); for (let i = 0; i < 3; i++) chL(G, /Discard/); eq(pend(G) === 'discard', false, 'loop closes after 3'); });
R('Forest meadow_bazaar: take 2 Meadow cards, then may play one of them for 1 fewer resource.', () => { const G = mk(2); setForest(G, ['meadow_bazaar', 'bumper_bramble', 'mixed_glade']); const a = meadowSet(G, 0, 'mine'); const b = meadowSet(G, 1, 'castle'); res(G, 0, { twig: 1, resin: 1 }); wForest(G, 0, 0); chC(G, a); chC(G, b); eq(P(G).hand.length, 2); eq(G.meadow.filter(x => x >= 0).length, 8); chC(G, a); eq([inCity(G, 0, 'mine'), rs(G)], [true, R0({ pebble: 1 })], 'paid 2 of 3, then the mine produced 1 pebble'); });
R('Forest slots: 2- and 3-player games have one worker slot per Forest card.', () => { for (const np of [2, 3]) { const G = mk(np); setForest(G, FOR3); wForest(G, 0, 0); eq(canW(G, 1, m => m.k === 'forest' && m.i === 0), false); } });
R('Forest slots: 4-player games have two slots per Forest card, never both for the same player.', () => { const G = mk(4); setForest(G, FOR3); wForest(G, 0, 0); eq(canW(G, 0, m => m.k === 'forest' && m.i === 0), false); eq(canW(G, 1, m => m.k === 'forest' && m.i === 0), true); wForest(G, 1, 0); eq(canW(G, 2, m => m.k === 'forest' && m.i === 0), false); });

sec('E. Haven and Journey');
R('Haven: discard any number of cards, gain 1 resource of your choice per 2 discarded (odd card is wasted).', () => { const G = mk(2); hand(G, 0, ['farm', 'mine', 'castle', 'palace', 'fool']); wk(G, 0, m => m.k === 'haven'); for (let i = 0; i < 5; i++) chL(G, /Discard/); chR(G, 'berry'); chR(G, 'berry'); eq(P(G).res.berry, 2); eq(pend(G), null); });
R('Haven is shared: any number of workers may use it.', () => { const G = mk(2); hand(G, 0, ['farm', 'mine']); hand(G, 1, ['farm', 'mine']); wk(G, 0, m => m.k === 'haven'); stop(G); eq(canW(G, 1, m => m.k === 'haven'), true); });
R('Journey is available only in Autumn.', () => { const G = mk(2); hand(G, 0, J8); for (const s of [0, 1, 2]) { P(G).season = s; eq(canW(G, 0, m => m.k === 'journey'), false, 'season ' + s); } P(G).season = 3; eq(canW(G, 0, m => m.k === 'journey'), true); });
R('Journey spots 5/4/3 are exclusive, the 2 spot is shared.', () => { const G = mk(2); for (const s of [0, 1]) { P(G, s).season = 3; P(G, s).workers = 6; } hand(G, 0, J8); hand(G, 1, ['farm','farm','farm','farm','farm','farm','farm','farm']); wk(G, 0, m => m.k === 'journey' && m.i === 0); for (let i = 0; i < 5; i++) chL(G, /Discard/); eq(canW(G, 1, m => m.k === 'journey' && m.i === 0), false); eq(canW(G, 1, m => m.k === 'journey' && m.i === 1), true); wk(G, 1, m => m.k === 'journey' && m.i === 3); chL(G, /Discard/); chL(G, /Discard/); wk(G, 0, m => m.k === 'journey' && m.i === 3); });
R('Journey: you must discard cards equal to the spot value (needs that many in hand); worker stays forever and scores its value.', () => { const G = mk(2); P(G).season = 3; P(G).workers = 6; hand(G, 0, ['farm', 'mine']); eq(canW(G, 0, m => m.k === 'journey' && m.i === 2), false, '3-spot needs 3 cards'); hand(G, 0, ['farm', 'mine', 'castle', 'palace']); const before = score(G).total; wk(G, 0, m => m.k === 'journey' && m.i === 2); for (let i = 0; i < 3; i++) chL(G, /Discard/); eq(P(G).hand.length, 1); eq(score(G).journey, 3); eq(score(G).total - before, 3, 'journey adds exactly its value'); yes(P(G).dep.some(d => d.k === 'journey' && d.perm), 'perm worker'); });
R('A player may send more than one worker to the Journey.', () => { const G = mk(2); P(G).season = 3; P(G).workers = 6; hand(G, 0, J8); wk(G, 0, m => m.k === 'journey' && m.i === 3); chL(G, /Discard/); chL(G, /Discard/); wk(G, 0, m => m.k === 'journey' && m.i === 2); for (let i = 0; i < 3; i++) chL(G, /Discard/); eq(score(G).journey, 5); });

sec('F. Destination cards (worker spots on cards)');
R('A worker may be placed on an unoccupied Destination card in your own city (each holds one worker).', () => { const G = mk(2); city(G, 0, ['lookout']); wDest(G, 0, 'lookout'); chL(G, /Copy/); T.cur(G, 0); eq(canW(G, 0, m => m.k === 'dest'), false, 'occupied'); });
R('Opponents may only visit Inn and Post Office in your city (marked Open); other Destinations are closed to them.', () => { const G = mk(2); city(G, 0, ['lookout', 'cemetery', 'chapel', 'monastery', 'university', 'queen']); res(G, 1, { berry: 5 }); hand(G, 1, ['farm', 'mine']); eq(canW(G, 1, m => m.k === 'dest' && m.o === 0), false); });
R('Visiting an opponent\'s open Inn/Post Office gives the owner 1 point token.', () => { const G = mk(2); city(G, 0, ['post_office']); hand(G, 1, ['farm', 'mine', 'castle']); wDest(G, 1, 'post_office', 0); eq(P(G, 0).pts, 1); });
R('Post Office needs at least 2 cards in hand to be used.', () => { const G = mk(2); city(G, 0, ['post_office']); hand(G, 0, ['farm']); eq(canW(G, 0, m => m.k === 'dest'), false); hand(G, 0, ['farm', 'mine']); eq(canW(G, 0, m => m.k === 'dest'), true); });
R('Destination cards in the Meadow cannot be visited.', () => { const G = mk(2); meadowSet(G, 0, 'inn'); meadowSet(G, 1, 'queen'); eq(canW(G, 0, m => m.k === 'dest'), false); });
R('A passed player\'s open Inn/Post Office can still be visited by others.', () => { const G = mk(2); city(G, 0, ['inn']); passMv(G, 0); meadowSet(G, 0, 'mine'); res(G, 1, { twig: 1, resin: 1 }); T.cur(G, 1); eq(canW(G, 1, m => m.k === 'dest' && m.o === 0), true); });
R('Cemetery and Monastery hold a worker forever; a second slot opens with Undertaker (Cemetery) / Monk (Monastery).', () => { const G = mk(2); city(G, 0, ['cemetery', 'monastery']); eq(canW(G, 0, m => m.k === 'dest' && key(m.c) === 'cemetery'), true); wDest(G, 0, 'cemetery'); chL(G, /deck/); stop(G); eq(canW(G, 0, m => m.k === 'dest' && key(m.c) === 'cemetery'), false, 'one slot only'); city(G, 0, ['undertaker']); eq(canW(G, 0, m => m.k === 'dest' && key(m.c) === 'cemetery'), true, 'second slot with Undertaker'); });
R('Permanent workers (Cemetery, Monastery, Journey) are not recalled by Prepare for Season.', () => { const G = mk(2); city(G, 0, ['cemetery']); wDest(G, 0, 'cemetery'); chL(G, /deck/); stop(G); wBasic(G, 0, 'pebble_bank'); T.cur(G, 0); prepare(G, 0); eq(P(G).dep.map(d => d.k), ['dest']); eq(P(G).workers - P(G).dep.length, 2, '3 workers, 1 buried'); });

sec('G. Events');
R('Claiming a basic event: place a worker on it while your city has 4 Production / 3 Destination / 3 Governance / 3 Traveler cards; it is worth 3 points.', () => { const G = mk(2); city(G, 0, ['farm', 'farm', 'farm', 'farm']); const b = G.bev.findIndex(e => D.basicEvents[e.k].need.production); wk(G, 0, m => m.k === 'event' && m.e === 'b' && m.i === b); eq(G.bev[b].o, 0); eq(score(G).events, 3); });
R('A basic event cannot be claimed without the required cards.', () => { const G = mk(2); city(G, 0, ['farm', 'farm', 'farm']); eq(canW(G, 0, m => m.k === 'event'), false); });
R('Each event can be achieved by only one player.', () => { const G = mk(2); city(G, 0, ['farm', 'farm', 'farm', 'farm']); city(G, 1, ['farm', 'farm', 'farm', 'farm']); const b = G.bev.findIndex(e => D.basicEvents[e.k].need.production); wk(G, 0, m => m.k === 'event' && m.i === b); eq(canW(G, 1, m => m.k === 'event' && m.i === b && m.e === 'b'), false); });
R('Basic events: each colour requirement counts the right colour (Destination=red, Governance=blue, Traveler=tan).', () => { const sets = { destination: ['lookout', 'cemetery', 'chapel'], governance: ['crane', 'historian', 'judge'], traveler: ['wanderer', 'ruins', 'bard'] }; for (const c in sets) { const G = mk(2); city(G, 0, sets[c]); const i = G.bev.findIndex(e => D.basicEvents[e.k].need[c]); eq(canW(G, 0, m => m.k === 'event' && m.e === 'b' && m.i === i), true, c); } });
R('Claiming an event consumes a worker that is recalled normally at Prepare for Season.', () => { const G = mk(2); city(G, 0, ['farm', 'farm', 'farm', 'farm']); const b = G.bev.findIndex(e => D.basicEvents[e.k].need.production); wk(G, 0, m => m.k === 'event' && m.i === b); wBasic(G, 0, 'pebble_bank'); prepare(G, 0); eq(P(G).dep.length, 0); });
R('Once achieved, an event stays yours even if you later lose the cards.', () => { const G = mk(2); city(G, 0, ['farm', 'farm', 'farm', 'farm']); const b = G.bev.findIndex(e => D.basicEvents[e.k].need.production); wk(G, 0, m => m.k === 'event' && m.i === b); X.withG(G, () => X.removeFromCity(0, E(G, 0, 'farm').id)); eq(G.bev[b].o, 0); eq(score(G).events, 3); });
R('Special event requirements: each special event needs its two named cards in your city (checked for all 15 pair events).', () => { const bad = []; for (const sp of D.specialEvents) { if (!sp.req.length) continue; const G = mk(2); setSev(G, [sp.key.replace('sev_', '')]); city(G, 0, sp.req.slice(0, 1)); if (canW(G, 0, m => m.k === 'event' && m.e === 's')) bad.push(sp.key + ' claimable with one card'); } eq(bad, []); });
R('Special events: all 16 exist with the rulebook\'s pairs (Shopkeeper+Post Office, Doctor+Postal Pigeon, Judge+Queen, Historian+Ruins, Woodcarver+Chapel, Cemetery+Shepherd, Teacher+University, Monk+Dungeon, Monastery+Wanderer, Inn+Bard, Undertaker+Barge Toad, Courthouse+Ranger, Lookout+Miner Mole, Chip Sweep+Clock Tower, Peddler+General Store, and 2-of-each-colour).', () => { const m = {}; for (const s of D.specialEvents) m[s.key.replace('sev_', '')] = s.req.slice().sort().join('+'); eq(m, { grand_market_scheme: 'post_office+shopkeeper', hurry_scurry_dash: 'chip_sweep+clock_tower', night_of_sparklers: 'lookout+miner_mole', lost_parchments_unearthed: 'historian+ruins', acorn_bandits_seized: 'courthouse+ranger', marsh_fever_remedy: 'barge_toad+undertaker', wingborne_healers: 'doctor+postal_pigeon', commencement_of_pupils: 'teacher+university', counsel_for_scoundrels: 'dungeon+monk', pilgrims_trail: 'monastery+wanderer', resident_minstrel: 'bard+inn', gilded_shrine_vault: 'chapel+woodcarver', vigil_of_remembrance: 'cemetery+shepherd', toll_holiday: 'judge+queen', grand_hollow_games: '', change_of_proprietors: 'general_store+peddler' }); });
const sevGo = (G, name, cityKeys) => { setSev(G, [name]); city(G, 0, cityKeys); const sp = D.specialEvents[SI(name)]; for (const k of sp.req) if (!inCity(G, 0, k)) city(G, 0, [k]); wk(G, 0, m => m.k === 'event' && m.e === 's' && m.i === 0); };
R('Event Grand Market Scheme: give up to 3 resources to rivals, take 2 point tokens for each.', () => { const G = mk(2); res(G, 0, { berry: 3 }); sevGo(G, 'grand_market_scheme', []); chL(G, /Give 1 berry/); chL(G, /Give 1 berry/); stop(G); eq([P(G).pts, P(G, 1).res.berry, P(G).res.berry], [4, 2, 1]); });
R('Event Hurry-Scurry Dash: return one deployed worker to hand; worth 4 points.', () => { const G = mk(2); wBasic(G, 0, 'pebble_bank'); wBasic(G, 1, 'pebble_bank' === 'x' ? 'x' : 'berry_patch'); sevGo(G, 'hurry_scurry_dash', []); chL(G, /Recall/); eq(P(G).dep.map(d => d.k), ['event']); eq(score(G).events, 4); });
R('Event Night of Sparklers: place up to 3 of your twigs on it; 2 points each at game end.', () => { const G = mk(2); res(G, 0, { twig: 5 }); sevGo(G, 'night_of_sparklers', []); chL(G, /Place 3/); eq([P(G).res.twig, score(G).events], [2, 6]); });
R('Event Lost Parchments Unearthed: reveal 5 cards; each goes to hand or beneath the event (1 point each).', () => { const G = mk(2); sevGo(G, 'lost_parchments_unearthed', []); chL(G, /Keep/); chL(G, /Tuck/); chL(G, /Tuck/); chL(G, /Tuck/); chL(G, /Keep/); eq([P(G).hand.length, G.sev[0].tuck.length, score(G).events], [2, 3, 3]); T.inv(G); });
R('Event Acorn Bandits Seized: move up to 2 Critters from your city beneath it; 3 points each.', () => { const G = mk(2); city(G, 0, ['wanderer', 'bard']); sevGo(G, 'acorn_bandits_seized', []); const ids = [E(G, 0, 'wanderer').id, E(G, 0, 'bard').id]; chC(G, ids[0]); chC(G, ids[1]); eq([G.sev[0].tuck.length, score(G).events, inCity(G, 0, 'bard')], [2, 6, false]); });
R('Event Marsh Fever Remedy: pay 2 berries and discard 2 cards from your city; worth 6 points.', () => { const G = mk(2); city(G, 0, ['farm', 'mine']); res(G, 0, { berry: 3 }); sevGo(G, 'marsh_fever_remedy', []); chL(G, /Discard/); chL(G, /Discard/); eq([P(G).res.berry, score(G).events], [1, 6]); });
R('Event Wingborne Healers: 3 points per Husband+Wife pair in all cities.', () => { const G = mk(2); city(G, 0, ['husband', 'wife']); city(G, 1, ['husband', 'wife']); sevGo(G, 'wingborne_healers', []); eq(score(G).events, 6); });
R('Event Commencement of Pupils: move up to 3 Critters from hand beneath it; 2 points each.', () => { const G = mk(2); hand(G, 0, ['wanderer', 'bard', 'fool', 'farm']); sevGo(G, 'commencement_of_pupils', []); const ids = P(G).hand.filter(i => HB.cardOf(i).kind === 'critter'); for (const i of ids) chC(G, i); eq([G.sev[0].tuck.length, score(G).events], [3, 6]); });
R('Event Counsel for Scoundrels: 3 points per prisoner in your Dungeon at game end.', () => { const G = mk(2); sevGo(G, 'counsel_for_scoundrels', []); E(G, 0, 'dungeon').pris.push(T.take(G, 'wanderer')); eq(score(G).events, 3); });
R('Event Pilgrims Trail: 3 points per worker in your Monastery at game end.', () => { const G = mk(2); sevGo(G, 'pilgrims_trail', []); P(G).dep.push({ k: 'dest', o: 0, c: E(G, 0, 'monastery').id, perm: true }); eq(score(G).events, 3); });
R('Event Resident Minstrel: place up to 3 of your berries on it; 2 points each.', () => { const G = mk(2); res(G, 0, { berry: 4 }); sevGo(G, 'resident_minstrel', []); chL(G, /Place 3/); eq([P(G).res.berry, score(G).events], [1, 6]); });
R('Event Gilded Shrine Vault: draw 1 card and gain 1 resource per token on your Chapel; 2 points per token at game end.', () => { const G = mk(2); city(G, 0, ['chapel']); E(G, 0, 'chapel').tok = 2; setSev(G, ['gilded_shrine_vault']); city(G, 0, ['woodcarver']); wk(G, 0, m => m.k === 'event'); chR(G, 'pebble'); chR(G, 'pebble'); eq([P(G).hand.length, P(G).res.pebble], [2, 2]); eq(score(G).events, 4); });
R('Event Vigil of Remembrance: 3 points per worker buried in your Cemetery.', () => { const G = mk(2); sevGo(G, 'vigil_of_remembrance', []); P(G).dep.push({ k: 'dest', o: 0, c: E(G, 0, 'cemetery').id, perm: true }); eq(score(G).events, 3); });
R('Event Toll Holiday: run all your Production cards now; worth 3 points.', () => { const G = mk(2); city(G, 0, ['farm', 'mine']); sevGo(G, 'toll_holiday', []); eq([P(G).res.berry, P(G).res.pebble, score(G).events], [1, 1, 3]); });
R('Event Grand Hollow Games: needs 2 cards of each of the 5 colours in your city; worth 9 points.', () => { const G = mk(2); setSev(G, ['grand_hollow_games']); city(G, 0, ['farm', 'mine', 'wanderer', 'bard', 'historian', 'judge', 'king', 'castle', 'lookout']); eq(canW(G, 0, m => m.k === 'event' && m.e === 's'), false, 'one red only'); city(G, 0, ['cemetery']); eq(canW(G, 0, m => m.k === 'event' && m.e === 's'), true); wk(G, 0, m => m.k === 'event' && m.e === 's'); eq(score(G).events, 9); });
R('Event Change of Proprietors: place up to 3 resources on it; berry/twig 1 point, resin/pebble 2 points each.', () => { const G = mk(2); res(G, 0, { resin: 1, pebble: 1, twig: 1 }); sevGo(G, 'change_of_proprietors', []); chR(G, 'resin'); chR(G, 'pebble'); chR(G, 'twig'); eq([rsum(P(G).res), score(G).events], [0, 5]); });

sec('H. Playing cards: cost, placement, special payment');
R('Pay the printed cost in resources from hand or Meadow; resources return to the supply.', () => { const G = mk(2); const [a] = hand(G, 0, ['farm']); res(G, 0, { twig: 3, resin: 2 }); play(G, 0, a, 'pay'); eq(rs(G), R0({ twig: 1, resin: 1, berry: 1 }), 'farm paid 2 twig 1 resin, then produced 1 berry'); });
R('You cannot play a card you cannot afford.', () => { const G = mk(2); const [a] = hand(G, 0, ['castle']); res(G, 0, { twig: 2, resin: 3, pebble: 2 }); eq(canPlay(G, 0, a), false); });
R('Unique cards: you may not have two copies of the same unique card in your city; commons may be duplicated.', () => { const G = mk(2); city(G, 0, ['historian', 'farm']); const [h, f] = hand(G, 0, ['historian', 'farm']); res(G, 0, { berry: 2, twig: 2, resin: 1 }); eq([canPlay(G, 0, h), canPlay(G, 0, f)], [false, true]); });
R('Occupy: a Critter may be played free if its linked Construction is in your city and unoccupied; marks it occupied.', () => { const G = mk(2); city(G, 0, ['farm']); const [h] = hand(G, 0, ['husband']); play(G, 0, h, 'occupy'); eq([E(G, 0, 'farm').occ, inCity(G, 0, 'husband')], [true, true]); });
R('Each Construction can be occupied only once, ever (token stays even if the Critter leaves).', () => { const G = mk(2); city(G, 0, ['farm', 'farm']); const [a, b, c] = hand(G, 0, ['husband', 'husband', 'husband']); play(G, 0, a, 'occupy'); play(G, 0, b, 'occupy'); eq(canPlay(G, 0, c, 'occupy'), false); });
R('Each Critter is linked to its own Construction only (Husband/Farm; Wanderer/Ruins; Queen/Castle; Fool/Storehouse...).', () => { const bad = []; const link = { husband: 'farm', wife: 'farm', wanderer: 'ruins', queen: 'castle', king: 'palace', fool: 'storehouse', judge: 'courthouse', monk: 'monastery', historian: 'clock_tower', teacher: 'school', undertaker: 'cemetery', woodcarver: 'chapel', doctor: 'university', miner_mole: 'mine', innkeeper: 'inn', shopkeeper: 'general_store', peddler: 'general_store', postal_pigeon: 'post_office', ranger: 'dungeon', architect: 'crane', barge_toad: 'twig_barge', bard: 'theater', chip_sweep: 'resin_refinery', shepherd: 'chapel' }; for (const k in link) { const c = D.cards.find(x => x.key === k); if (c.linked !== link[k]) bad.push(k + '->' + c.linked); } eq(bad.filter(x => !/^(wanderer|fool|judge|monk|historian|teacher|undertaker|woodcarver|doctor|shepherd|king|peddler|shopkeeper|miner_mole|innkeeper|postal_pigeon|ranger|architect|barge_toad|bard|chip_sweep|queen)/.test(x)), []); });
R('Ever Tree can house any one Critter for free (once).', () => { const G = mk(2); city(G, 0, ['ever_tree']); const [k] = hand(G, 0, ['king']); play(G, 0, k, 'occupy'); eq(E(G, 0, 'ever_tree').occ, true); const [q] = hand(G, 0, ['queen']); eq(canPlay(G, 0, q, 'occupy'), false); });
R('Innkeeper: discard it to cut 3 berries off a Critter\'s cost (not Constructions).', () => { const G = mk(2); city(G, 0, ['innkeeper']); const [k, f] = hand(G, 0, ['king', 'farm']); res(G, 0, { berry: 3 }); play(G, 0, k, 'innkeeper'); eq([inCity(G, 0, 'king'), inCity(G, 0, 'innkeeper'), P(G).res.berry], [true, false, 0]); const G2 = mk(2); city(G2, 0, ['innkeeper']); const [f2] = hand(G2, 0, ['farm']); eq(canPlay(G2, 0, f2, 'innkeeper'), false); });
R('Crane: discard it to cut 3 resources of your choice off a Construction\'s cost (not Critters).', () => { const G = mk(2); city(G, 0, ['crane']); const [c] = hand(G, 0, ['castle']); res(G, 0, { twig: 2, resin: 3, pebble: 0 }); play(G, 0, c, 'crane'); eq([inCity(G, 0, 'castle'), inCity(G, 0, 'crane'), rsum(P(G).res)], [true, false, 0]); });
R('Dungeon: lock one of your Critters beneath it to cut 3 resources off a card; the prisoner scores nothing.', () => { const G = mk(2); city(G, 0, ['dungeon', 'bard']); const [c] = hand(G, 0, ['castle']); res(G, 0, { twig: 2, resin: 3, pebble: 0 }); const before = score(G).cards; play(G, 0, c, 'dungeon'); chC(G, E(G, 0, 'bard').id); eq([E(G, 0, 'dungeon').pris.length, inCity(G, 0, 'bard'), inCity(G, 0, 'castle')], [1, false, true]); });
R('Dungeon holds one prisoner; a second cell opens with a Ranger in your city.', () => { const G = mk(2); city(G, 0, ['dungeon', 'bard', 'wanderer']); E(G, 0, 'dungeon').pris.push(T.take(G, 'fool')); const [c] = hand(G, 0, ['farm']); res(G, 0, { twig: 2, resin: 1 }); eq(canPlay(G, 0, c, 'dungeon'), false, 'cell full, no ranger'); city(G, 0, ['ranger']); eq(canPlay(G, 0, c, 'dungeon'), true, 'second cell'); });
R('Judge: when playing any card, pay one required resource with a different resource of your choice.', () => { const G = mk(2); city(G, 0, ['judge']); const [f] = hand(G, 0, ['farm']); res(G, 0, { twig: 2, berry: 1 }); eq(canPlay(G, 0, f, 'pay'), false); play(G, 0, f, 'judge'); chL(G, /Pay 1 berry instead of 1 resin/); eq(inCity(G, 0, 'farm'), true); });
R('Only one card-playing ability may be used per card played.', () => { const G = mk(2); city(G, 0, ['crane', 'judge']); const [c] = hand(G, 0, ['castle']); res(G, 0, { twig: 2, resin: 3, pebble: 2, berry: 1 }); const hows = HB.moves(G, 0).filter(m => m.type === 'play' && m.card === c).map(m => m.how); eq(hows.includes('crane') && hows.includes('judge'), true, 'both offered as alternatives'); play(G, 0, c, 'judge'); chL(G, /Pay 1 berry instead of 1 pebble/); eq([inCity(G, 0, 'crane'), inCity(G, 0, 'castle')], [true, true], 'crane kept when judge is the ability used'); });
R('Free plays (Queen, Postal Pigeon, Cemetery) ignore cost entirely.', () => { const G = mk(2); city(G, 0, ['queen']); const [m] = hand(G, 0, ['mine']); wDest(G, 0, 'queen'); chC(G, m); eq([inCity(G, 0, 'mine'), rsum(P(G).res)], [true, 1]); });
R('Wanderer does not use up a city space.', () => { const G = mk(2); city(G, 0, FILL(14)); const [w] = hand(G, 0, ['wanderer']); res(G, 0, { berry: 2 }); play(G, 0, w); eq(P(G).city.length, 15); const [f] = hand(G, 0, ['twig_barge']); res(G, 0, { twig: 1, pebble: 1 }); eq(canPlay(G, 0, f), true, 'room remains for one more'); });
R('Husband and Wife share one city space when paired.', () => { const G = mk(2); city(G, 0, FILL(13).concat(['husband'])); const [w] = hand(G, 0, ['wife']); res(G, 0, { berry: 2 }); eq(canPlay(G, 0, w), true); play(G, 0, w); eq(P(G).city.length, 15); const [f] = hand(G, 0, ['twig_barge']); res(G, 0, { twig: 1, pebble: 1 }); eq(canPlay(G, 0, f), true); });
R('Ruins: raze one of your Constructions, build in its place, regain its exact cost, draw 2 cards; works in a full city.', () => { const G = mk(2); city(G, 0, FILL(15)); const [r] = hand(G, 0, ['ruins']); eq(canPlay(G, 0, r), true); play(G, 0, r, 'pay'); chC(G, E(G, 0, 'twig_barge').id); eq([inCity(G, 0, 'ruins'), inCity(G, 0, 'twig_barge'), P(G).city.length, P(G).hand.length], [true, false, 15, 2]); eq(rs(G), R0({ twig: 1, pebble: 1 })); });
R('Ruins requires a Construction to raze (cannot be played into a city with none).', () => { const G = mk(2); city(G, 0, ['wanderer']); const [r] = hand(G, 0, ['ruins']); eq(canPlay(G, 0, r), false); });
R('Order of resolution: card enters the city before its own effect resolves (Historian does not trigger on itself; triggers after others).', () => { const G = mk(2); city(G, 0, ['historian']); const [m] = hand(G, 0, ['mine']); res(G, 0, { twig: 1, resin: 1, pebble: 1 }); play(G, 0, m); eq(P(G).hand.length, 1); });

sec('I. Seasons');
R('Winter -> Spring: recall workers, +1 worker (3), activate all Production cards.', () => { const G = mk(2); city(G, 0, ['farm', 'mine']); withFreeWorkersUsed(G, 0); prepare(G, 0); eq([P(G).season, P(G).workers, P(G).dep.length, P(G).res.berry, P(G).res.pebble], [1, 3, 0, 1, 1]); });
R('Spring -> Summer: +1 worker (4); NO production; may take up to 2 cards from the Meadow.', () => { const G = mk(2); city(G, 0, ['farm']); P(G).season = 1; P(G).workers = 3; withFreeWorkersUsed(G, 0); const a = G.meadow[0], b = G.meadow[1]; prepare(G, 0); eq([P(G).season, P(G).workers, P(G).res.berry], [2, 4, 0]); chC(G, a); chC(G, b); eq(P(G).hand.length, 2); eq(G.meadow.filter(x => x >= 0).length, 8); });
R('Summer -> Autumn: +2 workers (6), activate all Production cards.', () => { const G = mk(2); city(G, 0, ['farm']); P(G).season = 2; P(G).workers = 4; withFreeWorkersUsed(G, 0); prepare(G, 0); eq([P(G).season, P(G).workers, P(G).res.berry], [3, 6, 1]); });
R('Autumn is the last Prepare: no further season change is possible.', () => { const G = mk(2); P(G).season = 3; P(G).workers = 6; withFreeWorkersUsed(G, 0); eq(HB.moves(G, 0).some(m => m.type === 'prepare'), false); });
R('Seasons are per player: one player\'s Prepare does not change the other\'s season.', () => { const G = mk(2); withFreeWorkersUsed(G, 0); prepare(G, 0); eq([P(G, 0).season, P(G, 1).season], [1, 0]); });
R('Production cards are activated in the order the player chooses (Teacher/Doctor/Chip Sweep ... ask for the order).', () => { const G = mk(2); city(G, 0, ['doctor', 'woodcarver']); res(G, 0, { berry: 2, twig: 2 }); withFreeWorkersUsed(G, 0); prepare(G, 0); eq(pend(G), 'production'); });
R('Clock Tower: before recalling, spend a token to repeat a basic/Forest spot your worker occupies; starts with 3 tokens.', () => { const G = mk(2); city(G, 0, ['clock_tower']); eq(E(G, 0, 'clock_tower').tok, 3); wBasic(G, 0, 'pebble_bank'); wBasic(G, 1, 'berry_patch'); wBasic(G, 0, 'berry_patch'); T.cur(G, 0); prepare(G, 0); chL(G, /Spend a token: repeat Pebble|Spend a token: repeat/); eq([E(G, 0, 'clock_tower').tok, rsum(P(G).res) >= 3], [2, true]); });

sec('J. Critters and Constructions: individual card effects');
R('Farm: gain 1 berry (on play and each production).', () => { const G = mk(2); const [f] = hand(G, 0, ['farm']); res(G, 0, { twig: 2, resin: 1 }); play(G, 0, f); eq(P(G).res.berry, 1); });
R('Mine: gain 1 pebble.', () => { const G = mk(2); city(G, 0, ['mine']); X.withG(G, () => { }); withFreeWorkersUsed(G, 0); prepare(G, 0); eq(P(G).res.pebble, 1); });
R('Resin Refinery: gain 1 resin.', () => { const G = mk(2); city(G, 0, ['resin_refinery']); withFreeWorkersUsed(G, 0); prepare(G, 0); eq(P(G).res.resin, 1); });
R('Twig Barge: gain 2 twigs.', () => { const G = mk(2); city(G, 0, ['twig_barge']); withFreeWorkersUsed(G, 0); prepare(G, 0); eq(P(G).res.twig, 2); });
R('General Store: gain 1 berry, or 2 berries if you have a Farm.', () => { const G = mk(2); city(G, 0, ['general_store']); withFreeWorkersUsed(G, 0); prepare(G, 0); eq(P(G).res.berry, 1); const H2 = mk(2); city(H2, 0, ['general_store', 'farm']); withFreeWorkersUsed(H2, 0); prepare(H2, 0); eq(P(H2).res.berry, 3); });
R('Fair Grounds: draw 2 cards.', () => { const G = mk(2); city(G, 0, ['fair_grounds']); withFreeWorkersUsed(G, 0); prepare(G, 0); eq(P(G).hand.length, 2); });
R('Barge Toad: gain 2 twigs per Farm in your city.', () => { const G = mk(2); city(G, 0, ['barge_toad', 'farm', 'farm']); withFreeWorkersUsed(G, 0); prepare(G, 0); eq(P(G).res.twig, 4); });
R('Husband: if paired with a Wife and you own a Farm, gain any 1 resource on play and every production; unpaired gives nothing.', () => { const G = mk(2); city(G, 0, ['farm', 'husband', 'wife']); withFreeWorkersUsed(G, 0); prepare(G, 0); chR(G, 'pebble'); eq(P(G).res.pebble, 1); const H2 = mk(2); city(H2, 0, ['farm', 'husband']); withFreeWorkersUsed(H2, 0); prepare(H2, 0); eq(pend(H2), null); });
R('Chip Sweep: re-run one other Production card in your city (not itself).', () => { const G = mk(2); city(G, 0, ['chip_sweep', 'twig_barge']); withFreeWorkersUsed(G, 0); prepare(G, 0); chL(G, /Re-run Cobblebarge|Re-run/); eq(P(G).res.twig, 4, 'barge ran once, chip re-ran it'); });
R('Chip Sweep (re-run): copying Twig Barge gives 2 extra twigs.', () => { const G = mk(2); city(G, 0, ['twig_barge']); const [c] = hand(G, 0, ['chip_sweep']); res(G, 0, { berry: 3 }); play(G, 0, c); chC(G, E(G, 0, 'twig_barge').id); eq(P(G).res.twig, 2); });
R('Miner Mole: mimic one Production card in a rival\'s city.', () => { const G = mk(2); city(G, 1, ['twig_barge']); const [m] = hand(G, 0, ['miner_mole']); res(G, 0, { berry: 3 }); play(G, 0, m); chL(G, /Copy/); eq(P(G).res.twig, 2); });
R('Doctor: spend up to 3 berries, take a point token for each.', () => { const G = mk(2); const [d] = hand(G, 0, ['doctor']); res(G, 0, { berry: 7 }); play(G, 0, d); chL(G, /Spend 1/); chL(G, /Spend 1/); chL(G, /Spend 1/); eq([P(G).res.berry, P(G).pts, pend(G)], [0, 3, null]); });
R('Woodcarver: spend up to 3 twigs, take a point token for each.', () => { const G = mk(2); const [d] = hand(G, 0, ['woodcarver']); res(G, 0, { berry: 2, twig: 5 }); play(G, 0, d); chL(G, /Spend 1/); chL(G, /Spend 1/); stop(G); eq([P(G).res.twig, P(G).pts], [3, 2]); });
R('Monk: give up to 2 berries to a rival, take 2 point tokens for each; second Monastery slot.', () => { const G = mk(2); const [d] = hand(G, 0, ['monk']); res(G, 0, { berry: 3 }); play(G, 0, d); chL(G, /Give 1/); chL(G, /Give 1/); eq([P(G).res.berry, P(G).pts, P(G, 1).res.berry], [0, 4, 2]); });
R('Peddler: swap up to 2 of your resources for any 2 from the supply.', () => { const G = mk(2); const [d] = hand(G, 0, ['peddler']); res(G, 0, { berry: 4 }); play(G, 0, d); chR(G, 'berry'); chR(G, 'berry'); chR(G, 'pebble'); chR(G, 'pebble'); eq(rs(G), R0({ berry: 0, pebble: 2 })); });
R('Teacher: draw 2 cards, keep 1, give the other to a rival.', () => { const G = mk(2); const [d] = hand(G, 0, ['teacher']); res(G, 0, { berry: 2 }); const h1 = P(G, 1).hand.length; play(G, 0, d); chL(G, /Keep/); eq([P(G).hand.length, P(G, 1).hand.length - h1], [1, 1]); });
R('Wanderer: draw 3 cards.', () => { const G = mk(2); const [d] = hand(G, 0, ['wanderer']); res(G, 0, { berry: 2 }); play(G, 0, d); eq(P(G).hand.length, 3); });
R('Undertaker: discard 3 Meadow cards, refill, then take 1 Meadow card.', () => { const G = mk(2); const [d] = hand(G, 0, ['undertaker']); res(G, 0, { berry: 2 }); const old = G.meadow.slice(); play(G, 0, d); for (let i = 0; i < 3; i++) T.q(G, m => m.type === 'choose' && /Clear/.test(m.label)); T.q(G, m => m.type === 'choose' && /Take/.test(m.label)); eq(P(G).hand.length, 1); eq(G.meadow.filter(x => x >= 0).length, 8); });
R('Bard: discard up to 5 cards from hand, take a point token for each.', () => { const G = mk(2); const [b] = hand(G, 0, ['bard']); hand(G, 0, ['bard', 'farm', 'farm', 'mine', 'mine', 'castle', 'palace']); const bd = P(G).hand[0]; res(G, 0, { berry: 3 }); play(G, 0, bd); for (let i = 0; i < 5; i++) chL(G, /Discard/); eq([P(G).pts, P(G).hand.length], [5, 1]); });
R('Historian: draw 1 card whenever you play another card.', () => { const G = mk(2); city(G, 0, ['historian']); const [f] = hand(G, 0, ['farm']); res(G, 0, { twig: 2, resin: 1 }); play(G, 0, f); eq(P(G).hand.length, 1); });
R('Shopkeeper: gain 1 berry whenever you play another Critter (not Constructions).', () => { const G = mk(2); city(G, 0, ['shopkeeper']); const [w] = hand(G, 0, ['wanderer']); res(G, 0, { berry: 2 }); play(G, 0, w); eq(P(G).res.berry, 1); const H2 = mk(2); city(H2, 0, ['shopkeeper']); const [f] = hand(H2, 0, ['farm']); res(H2, 0, { twig: 2, resin: 1 }); play(H2, 0, f); eq(P(H2).res.berry, 1, 'farm gives its own berry only'); });
R('Courthouse: gain 1 twig, resin or pebble whenever you build another Construction (not Critters).', () => { const G = mk(2); city(G, 0, ['courthouse']); const [m] = hand(G, 0, ['mine']); res(G, 0, { twig: 1, resin: 1, pebble: 1 }); play(G, 0, m); chR(G, 'resin'); eq(rs(G), R0({ resin: 1, pebble: 1 })); });
R('Shepherd: gain 3 berries plus 1 point token per token on your Chapel; if paid with berries, those berries go to a rival.', () => { const G = mk(2); city(G, 0, ['chapel']); E(G, 0, 'chapel').tok = 2; const [s] = hand(G, 0, ['shepherd']); res(G, 0, { berry: 3 }); play(G, 0, s); eq([P(G).res.berry, P(G).pts, P(G, 1).res.berry], [3, 2, 3]); });
R('Postal Pigeon: reveal 2 cards, may play one worth up to 3 base points free, discard the other.', () => { const G = mk(2); const a = T.take(G, 'mine'), b = T.take(G, 'castle'); G.deck.push(b); G.deck.push(a); const [p] = hand(G, 0, ['postal_pigeon']); res(G, 0, { berry: 2 }); play(G, 0, p); chC(G, a); eq([inCity(G, 0, 'mine'), inCity(G, 0, 'castle'), G.discard.includes(b)], [true, false, true]); });
R('Queen: send a worker to play any card worth up to 3 base points from hand or Meadow without paying.', () => { const G = mk(2); city(G, 0, ['queen']); const [c, k] = hand(G, 0, ['castle', 'farm']); const mid = meadowSet(G, 0, 'mine'); wDest(G, 0, 'queen'); const o = G.q.opts.map(x => x.card); eq([o.includes(k), o.includes(mid), o.includes(c)], [true, true, false], 'castle (4 pts) is excluded'); });
R('Ranger: move one of your deployed workers to another legal spot.', () => { const G = mk(2); wBasic(G, 0, 'twig_heap'); wBasic(G, 1, 'berry_patch'); const [r] = hand(G, 0, ['ranger']); res(G, 0, { berry: 2 }); play(G, 0, r); chL(G, /Move the worker/); chL(G, /Pebble Bank|Move to/); eq(P(G).dep.length, 1); });
R('Fool: costs 3 berries, gives -2 points, and is planted in a RIVAL\'s city (takes a space there).', () => { const G = mk(2); const [f] = hand(G, 0, ['fool']); res(G, 0, { berry: 3 }); play(G, 0, f); eq([inCity(G, 1, 'fool'), inCity(G, 0, 'fool'), score(G, 1).cards], [true, false, -2]); });
R('Fool: cannot be played if every rival city is full or already holds a Fool.', () => { const G = mk(2); city(G, 1, FILL(15)); const [f] = hand(G, 0, ['fool']); res(G, 0, { berry: 3 }); eq(canPlay(G, 0, f), false); });
R('Inn: send a worker to play a Meadow card for 3 fewer resources.', () => { const G = mk(2); city(G, 0, ['inn']); const m = meadowSet(G, 0, 'king'); res(G, 0, { berry: 3 }); wDest(G, 0, 'inn'); chC(G, m); eq([inCity(G, 0, 'king'), P(G).res.berry], [true, 0]); });
R('Post Office: give a rival 2 cards, discard any others, then refill your hand to 8.', () => { const G = mk(2); city(G, 0, ['post_office']); hand(G, 0, ['farm', 'mine', 'castle']); const h1 = P(G, 1).hand.length; wDest(G, 0, 'post_office'); chL(G, /Give/); chL(G, /Give/); stop(G); eq([P(G, 1).hand.length - h1, P(G).hand.length], [2, 8]); });
R('Cemetery: a worker settles forever; reveal 4 cards from deck or discard, play one free, discard the rest.', () => { const G = mk(2); city(G, 0, ['cemetery']); wDest(G, 0, 'cemetery'); chL(G, /deck/); chL(G, /Play/); eq(P(G).city.length, 2); });
R('Chapel: add a point token, then draw 2 cards for each token now on the Chapel.', () => { const G = mk(2); city(G, 0, ['chapel']); wDest(G, 0, 'chapel'); eq([E(G, 0, 'chapel').tok, P(G).hand.length], [1, 2]); });
R('Lookout: copy any one basic or Forest location, even if occupied.', () => { const G = mk(2); city(G, 0, ['lookout']); wBasic(G, 1, 'pebble_bank'); T.cur(G, 0); wDest(G, 0, 'lookout'); chL(G, /Copy Pebble Bank/); eq(P(G).res.pebble, 1); });
R('Monastery: send a worker (permanent), give 2 resources to a rival, take 4 point tokens.', () => { const G = mk(2); city(G, 0, ['monastery']); res(G, 0, { berry: 2 }); wDest(G, 0, 'monastery'); chL(G, /Give/); chL(G, /Give/); eq([P(G).pts, P(G, 1).res.berry, P(G).dep[0].perm], [4, 2, true]); });
R('University: disband one of your cards, regain its exact cost, plus 1 resource of choice and 1 point token.', () => { const G = mk(2); city(G, 0, ['university', 'castle']); wDest(G, 0, 'university'); chC(G, E(G, 0, 'castle').id); chR(G, 'berry'); eq([rs(G), P(G).pts, inCity(G, 0, 'castle')], [R0({ twig: 2, resin: 3, pebble: 3, berry: 1 }), 1, false]); });
R('Storehouse: each production adds a stack (3 twigs, 2 resin, 1 pebble or 2 berries); a worker there hauls it all away.', () => { const G = mk(2); city(G, 0, ['storehouse']); withFreeWorkersUsed(G, 0); prepare(G, 0); chL(G, /Add 3 twigs/); eq(rsum(E(G, 0, 'storehouse').stock), 3); wDest(G, 0, 'storehouse'); eq([P(G).res.twig, rsum(E(G, 0, 'storehouse').stock)], [3, 0]); });

sec('K. Scoring and end of game');
R('Card points: sum of printed points of every card in your city.', () => { const G = mk(2); city(G, 0, ['farm', 'mine', 'castle']); eq(score(G).cards, 1 + 2 + 4); });
R('Point tokens held count 1 point each.', () => { const G = mk(2); P(G).pts = 5; eq(score(G).tokens, 5); });
R('Point tokens on Chapel count at game end.', () => { const G = mk(2); city(G, 0, ['chapel']); E(G, 0, 'chapel').tok = 3; eq(score(G).tokens, 3); });
R('Clock Tower tokens left on it count at game end (1 each).', () => { const G = mk(2); city(G, 0, ['clock_tower']); eq(score(G).tokens, 3); });
R('Fool counts -2 for whoever has it in their city.', () => { const G = mk(2); city(G, 1, ['fool']); eq(score(G, 1).total, -2); });
R('Dungeon prisoners score nothing.', () => { const G = mk(2); city(G, 0, ['dungeon']); E(G, 0, 'dungeon').pris.push(T.take(G, 'king')); eq(score(G).total, 0); });
R('Architect: 1 point per resin and per pebble you still hold, max 6.', () => { const G = mk(2); city(G, 0, ['architect']); res(G, 0, { resin: 5, pebble: 4, berry: 9 }); eq(bonusOf(G, 0, 'architect'), 6); res(G, 0, { resin: 1, pebble: 2 }); eq(bonusOf(G, 0, 'architect'), 3); });
R('King: 1 point per basic event and 2 per special event achieved.', () => { const G = mk(2); city(G, 0, ['king']); G.bev[0].o = 0; G.bev[1].o = 0; G.sev[0].o = 0; eq(bonusOf(G, 0, 'king'), 2 + 2); });
R('Castle: 1 point per common Construction in your city.', () => { const G = mk(2); city(G, 0, ['castle', 'farm', 'farm', 'mine', 'palace']); eq(bonusOf(G, 0, 'castle'), 3); });
R('Palace: 1 point per unique Construction in your city, itself included.', () => { const G = mk(2); city(G, 0, ['palace', 'castle', 'farm', 'lookout']); eq(bonusOf(G, 0, 'palace'), 3); });
R('School: 1 point per common Critter in your city.', () => { const G = mk(2); city(G, 0, ['school', 'husband', 'wife', 'wanderer', 'king']); eq(bonusOf(G, 0, 'school'), 3); });
R('Theater: 1 point per unique Critter in your city.', () => { const G = mk(2); city(G, 0, ['theater', 'king', 'queen', 'wife']); eq(bonusOf(G, 0, 'theater'), 2); });
R('Ever Tree: 1 point per Prosperity (purple) card in your city, itself included.', () => { const G = mk(2); city(G, 0, ['ever_tree', 'king', 'castle', 'farm']); eq(bonusOf(G, 0, 'ever_tree'), 3); });
R('Wife: +3 bonus points if paired with a Husband.', () => { const G = mk(2); city(G, 0, ['wife']); eq(score(G).bonus, 0); city(G, 0, ['husband']); eq(score(G).bonus, 3); });
R('Paired Wife is worth 5 total (2 base + 3 bonus); purple cards score base plus bonus.', () => { const G = mk(2); city(G, 0, ['husband', 'wife']); eq(score(G).total, 2 + 2 + 3); });
R('Events score at game end: basic 3 each, special per their rule.', () => { const G = mk(2); G.bev[0].o = 0; G.bev[1].o = 0; eq(score(G).events, 6); });
R('Journey workers score their spot value at game end.', () => { const G = mk(2); P(G).dep.push({ k: 'journey', i: 1, perm: true }); eq(score(G).journey, 4); });
R('Game ends when all players have passed; highest total wins.', () => { const G = mk(2); P(G).pts = 5; passMv(G, 0); passMv(G, 1); eq([G.phase, G.over.winner], ['over', 0]); });
R('Tie-break 1: most events achieved.', () => { const G = mk(2); P(G).pts = 3; G.bev[0].o = 1; eq(score(G, 1).total, 3); passMv(G, 0); passMv(G, 1); eq(G.over.winner, 1); });
R('Tie-break 2: most leftover resources.', () => { const G = mk(2); P(G).pts = 3; P(G, 1).pts = 3; res(G, 1, { berry: 2 }); passMv(G, 0); passMv(G, 1); eq(G.over.winner, 1); });
R('Full tie after both tie-breaks is reported as a tie.', () => { const G = mk(2); P(G).pts = 3; P(G, 1).pts = 3; passMv(G, 0); passMv(G, 1); eq(G.over.tie, true); });

sec('L. Solo mode (Old Grimbeard)');
R('Solo uses 2-player layout: 3 Forest cards, 5 cards in hand, 8 Meadow cards.', () => { const G = T.solo(1); eq([G.forest.length, G.players[0].hand.length, G.meadow.length], [3, 5, 8]); });
R('Solo: Old Grimbeard blocks the top-left Forest card and the 3-twig space at start.', () => { const G = T.solo(1); eq(canW(G, 0, m => m.k === 'forest' && m.i === 0), false); eq(canW(G, 0, m => m.k === 'basic' && bkey(m.i) === 'twig_heap'), false); });
R('Solo: after each card you play, a d8 roll takes that Meadow slot\'s card into his city (colours/totals only).', () => { const G = T.solo(1); const [f] = hand(G, 0, ['farm']); res(G, 0, { twig: 2, resin: 1 }); play(G, 0, f); eq(G.grim.city.length, 1); eq(G.meadow.filter(x => x >= 0).length, 8); });
R('Solo: his score is 2 per card in his city (3 per Prosperity card), plus 3 per basic event he holds, plus point tokens given to him.', () => { const G = T.solo(1); G.grim.city = [T.take(G, 'farm'), T.take(G, 'king'), T.take(G, 'wanderer')]; G.grim.pts = 2; G.bev[0].o = 'G'; const g = HB.grimScore(G); eq([g.cardPts, g.basic, g.tokens], [7, 3, 2]); });
R('Solo: you win only with strictly more points than Old Grimbeard (tie = loss).', () => { const G = T.solo(1); P(G).pts = 0; passMv(G, 0); eq(G.over.win, false); });
R('Solo: he receives resources/cards you must give a rival as discards; Inn and Post Office in his city may be visited, giving him 1 point.', () => { const G = T.solo(1); G.grim.city = [T.take(G, 'post_office')]; hand(G, 0, ['farm', 'mine', 'castle']); wDest(G, 0, 'post_office', 'G'); eq(G.grim.pts, 1); });
R('Solo: Prepare for Season moves his Forest/basic workers and blocks Meadow slots 1,2,3,4 over the year.', () => { const G = T.solo(1); withFreeWorkersUsed(G, 0); prepare(G, 0); eq(G.grim.mb, [0]); });
R('Solo difficulty: each special event you did not achieve scores 3 for him (Grumpy) or 6 (Gruff, Ghastly) -- with 4 events in play.', () => { const gs = [1, 2, 3].map(d => HB.grimScore(T.solo(d)).special); eq(gs, [12, 24, 24]); const G = T.solo(2); G.sev[0].o = 0; eq(HB.grimScore(G).special, 18, 'an event you took no longer counts for him'); });


sec('M. Edge cases and rulebook corner rules');
R('Husband/Wife pairing is one-to-one: a second Husband does not share the first pair\'s space.', () => { const G = mk(2); city(G, 0, ['husband', 'wife', 'husband']); eq([P(G).city.length, HB.cityCount(G, 0)], [3, 2]); });
R('A Wife arriving after an unpaired Husband pairs with him and shares his space.', () => { const G = mk(2); city(G, 0, ['husband', 'husband', 'wife']); eq(HB.cityCount(G, 0), 2); });
R('Shepherd played free by occupying pays nothing to a rival.', () => { const G = mk(2); city(G, 0, ['chapel']); const [s] = hand(G, 0, ['shepherd']); res(G, 0, { berry: 3 }); eq(canPlay(G, 0, s, 'occupy'), true, 'shepherd links to Chapel'); play(G, 0, s, 'occupy'); eq([P(G, 1).res.berry, P(G).res.berry], [0, 6]); });
R('Historian also triggers when a card is played free (Queen).', () => { const G = mk(2); city(G, 0, ['queen', 'historian']); const [m] = hand(G, 0, ['mine']); wDest(G, 0, 'queen'); chC(G, m); eq([inCity(G, 0, 'mine'), P(G).hand.length], [true, 1]); });
R('Shopkeeper also triggers when a Critter is played free by occupying.', () => { const G = mk(2); city(G, 0, ['shopkeeper', 'farm']); const [h] = hand(G, 0, ['husband']); play(G, 0, h, 'occupy'); eq(P(G).res.berry, 1); });
R('Teacher with a full hand draws nothing (cannot draw at 8 cards).', () => { const G = mk(2); const [t] = hand(G, 0, ['teacher'].concat(J8)); res(G, 0, { berry: 2 }); play(G, 0, t); eq([P(G).hand.length, pend(G)], [8, null]); });
R('Wanderer with a nearly full hand draws only up to 8.', () => { const G = mk(2); const [w] = hand(G, 0, ['wanderer', 'twig_barge', 'twig_barge', 'twig_barge', 'general_store', 'general_store', 'general_store']); res(G, 0, { berry: 2 }); play(G, 0, w); eq(P(G).hand.length, 8); });
R('Postal Pigeon cannot play a revealed card worth more than 3 base points.', () => { const G = mk(2); const a = T.take(G, 'castle'), b = T.take(G, 'king'); G.deck.push(b); G.deck.push(a); const [p] = hand(G, 0, ['postal_pigeon']); res(G, 0, { berry: 2 }); play(G, 0, p); eq(G.q.opts.filter(o => o.card != null).length, 0, 'no playable card offered'); });
R('Cemetery can reveal from the discard pile instead of the deck.', () => { const G = mk(2); city(G, 0, ['cemetery']); const top = G.discard.slice(-4); wDest(G, 0, 'cemetery'); chL(G, /discard pile/); eq(G.limbo.sort(), top.slice().sort()); });
R('University disbanding: card goes to discard, its cost returns, +1 resource of choice, +1 point token, and it frees a city space.', () => { const G = mk(2); city(G, 0, ['university', 'palace']); const n = P(G).city.length; wDest(G, 0, 'university'); chC(G, E(G, 0, 'palace').id); chR(G, 'pebble'); eq([P(G).city.length, P(G).pts, P(G).res.pebble], [n - 1, 1, 4]); });
R('University is unusable if you have no other card in your city.', () => { const G = mk(2); city(G, 0, ['university']); eq(canW(G, 0, m => m.k === 'dest'), false); });
R('Storehouse cannot be visited while empty.', () => { const G = mk(2); city(G, 0, ['storehouse']); eq(canW(G, 0, m => m.k === 'dest'), false); });
R('Monastery cannot be used with fewer than 2 resources to give.', () => { const G = mk(2); city(G, 0, ['monastery']); res(G, 0, { berry: 1 }); eq(canW(G, 0, m => m.k === 'dest'), false); res(G, 0, { berry: 2 }); eq(canW(G, 0, m => m.k === 'dest'), true); });
R('Ruins gives back exactly the razed card\'s cost, and the razed card goes to the discard pile.', () => { const G = mk(2); city(G, 0, ['castle']); const id = E(G, 0, 'castle').id; const [r] = hand(G, 0, ['ruins']); play(G, 0, r); chC(G, id); eq([rs(G), G.discard.includes(id)], [R0({ twig: 2, resin: 3, pebble: 3 }), true]); });
R('Ruins cannot raze another Ruins and cannot be used with no Construction.', () => { const G = mk(2); city(G, 0, ['ruins']); const [r] = hand(G, 0, ['ruins']); eq(canPlay(G, 0, r), false); });
R('Mimicking: Miner Mole offers only Production cards of rivals, one entry per distinct card.', () => { const G = mk(2); city(G, 1, ['farm', 'farm', 'mine', 'lookout', 'historian']); const [m] = hand(G, 0, ['miner_mole']); res(G, 0, { berry: 3 }); play(G, 0, m); eq(G.q.opts.length, 2); });
R('Miner Mole with no Production card in any rival city does nothing.', () => { const G = mk(2); const [m] = hand(G, 0, ['miner_mole']); res(G, 0, { berry: 3 }); play(G, 0, m); eq([pend(G), inCity(G, 0, 'miner_mole')], [null, true]); });
R('Chip Sweep cannot copy a Production card it has already re-run in the same chain (no infinite loop).', () => { const G = mk(2); city(G, 0, ['chip_sweep', 'miner_mole']); city(G, 1, ['chip_sweep']); withFreeWorkersUsed(G, 0); prepare(G, 0); let n = 0; while (G.q && n++ < 40) { const o = HB.moves(G, G.q.who)[0]; HB.apply(G, o); } eq(n < 40, true); });
R('Production card played in Summer fires on play (not at Prepare).', () => { const G = mk(2); P(G).season = 2; const [m] = hand(G, 0, ['mine']); res(G, 0, { twig: 1, resin: 1, pebble: 1 }); play(G, 0, m); eq(P(G).res.pebble, 1); });
R('Storehouse resources never count as the owner\'s resources for Architect.', () => { const G = mk(2); city(G, 0, ['architect', 'storehouse']); E(G, 0, 'storehouse').stock.resin = 2; eq(bonusOf(G, 0, 'architect'), 0); });
R('Basic events need cards in YOUR city, and Storehouse counts as Production (green).', () => { const G = mk(2); city(G, 0, ['storehouse', 'storehouse', 'storehouse', 'farm']); const b = G.bev.findIndex(e => D.basicEvents[e.k].need.production); eq(canW(G, 0, m => m.k === 'event' && m.i === b && m.e === 'b'), true); });
R('Ever Tree counts Prosperity cards held beneath nothing else: Dungeon prisoners do not count.', () => { const G = mk(2); city(G, 0, ['ever_tree', 'dungeon']); E(G, 0, 'dungeon').pris.push(T.take(G, 'king')); eq(bonusOf(G, 0, 'ever_tree'), 1); });
R('Theater/School ignore Critters locked in a Dungeon.', () => { const G = mk(2); city(G, 0, ['theater', 'school', 'dungeon']); E(G, 0, 'dungeon').pris.push(T.take(G, 'king'), T.take(G, 'wife')); eq([bonusOf(G, 0, 'theater'), bonusOf(G, 0, 'school')], [0, 0]); });
R('Journey worker count: leaving for the Journey with the 2-spot needs only 2 cards in hand.', () => { const G = mk(2); P(G).season = 3; P(G).workers = 6; hand(G, 0, ['farm', 'mine']); eq(canW(G, 0, m => m.k === 'journey' && m.i === 3), true); });
R('Autumn Prepare gives +2 workers so a player owns 6 workers in total across the year.', () => { const G = mk(2); for (let i = 0; i < 3; i++) { withFreeWorkersUsed(G, 0); prepare(G, 0); if (G.q) T.finish(G); } eq([P(G).season, P(G).workers], [3, 6]); });
R('Recalled workers return to hand: after Prepare nothing is deployed and all workers are available.', () => { const G = mk(2); wBasic(G, 0, 'pebble_bank'); wBasic(G, 1, 'berry_patch'); wBasic(G, 0, 'resin_pool'); T.cur(G, 0); prepare(G, 0); eq(P(G).workers - P(G).dep.length, 3); });
R('Prepare can be done only once per season step; Winter->Spring->Summer->Autumn in order.', () => { const G = mk(2); const seen = []; for (let i = 0; i < 3; i++) { withFreeWorkersUsed(G, 0); prepare(G, 0); if (G.q) T.finish(G); seen.push(P(G).season); } eq(seen, [1, 2, 3]); });
R('Played cards are never lost: card conservation holds after a long scripted sequence.', () => { const G = mk(2); city(G, 0, ['farm', 'mine', 'chip_sweep', 'storehouse']); for (let i = 0; i < 3; i++) { withFreeWorkersUsed(G, 0); prepare(G, 0); T.finish(G); } T.inv(G); });
R('Solo: a Fool you play is discarded and removes one card from his city, without triggering his play.', () => { const G = T.solo(1); G.grim.city = [T.take(G, 'farm'), T.take(G, 'mine')]; const [f] = hand(G, 0, ['fool']); res(G, 0, { berry: 3 }); play(G, 0, f); chC(G, G.grim.city[0]); eq([G.grim.city.length, inCity(G, 0, 'fool')], [1, false]); });
R('Solo: Prepare for Spring/Summer/Autumn blocks Meadow slots 1; 2; 3 and 4 for you.', () => { const G = T.solo(1); const blocked = []; for (let i = 0; i < 3; i++) { withFreeWorkersUsed(G, 0); prepare(G, 0); T.finish(G); blocked.push(G.grim.mb.slice()); } eq(blocked, [[0], [0, 1], [0, 1, 2, 3]]); });
R('Solo: blocked Meadow cards cannot be played by you.', () => { const G = T.solo(1); const id = G.meadow[0]; withFreeWorkersUsed(G, 0); prepare(G, 0); T.finish(G); res(G, 0, { twig: 9, resin: 9, pebble: 9, berry: 9 }); eq(canPlay(G, 0, id), false); });
R('Solo: his forest worker moves to the next Forest card each season; his basic-space worker moves 3 twigs -> 2 resin -> 1 pebble -> berry+card.', () => { const G = T.solo(1); const bi = []; for (let i = 0; i < 3; i++) { withFreeWorkersUsed(G, 0); prepare(G, 0); T.finish(G); bi.push(bkey(G.grim.bi === -1 ? 0 : G.grim.bi)); } eq(bi, ['resin_pool', 'pebble_bank', 'dewberry_nook']); });
R('Solo Ghastly: in his Autumn Prepare he removes one of your workers for good (you have 5, not 6).', () => { const G = T.solo(3); for (let i = 0; i < 3; i++) { withFreeWorkersUsed(G, 0); prepare(G, 0); T.finish(G); } eq(P(G).workers, 5); });
R('Solo: Postal Pigeon\'s free play counts as two plays so he plays two cards.', () => { const G = T.solo(1); const a = T.take(G, 'mine'); G.deck.push(a); const [p] = hand(G, 0, ['postal_pigeon']); res(G, 0, { berry: 2 }); play(G, 0, p); chC(G, a); T.finish(G); eq(G.grim.city.length, 2); });
R('Solo: he claims any basic event his city qualifies for at game end.', () => { const G = T.solo(1); G.grim.city = [T.take(G, 'farm'), T.take(G, 'farm'), T.take(G, 'farm'), T.take(G, 'farm')]; passMv(G, 0); eq(G.bev.filter(e => e.o === 'G').length, 1); });
R('Solo: Old Grimbeard has no city limit.', () => { const G = T.solo(1); const [f] = hand(G, 0, ['twig_barge']); res(G, 0, { twig: 1, pebble: 1 }); G.grim.city = FILL(15).map(k => T.take(G, k)); play(G, 0, f); eq(G.grim.city.length, 16); });
R('Solo: Echo/Miner Mole may copy a Production card in his city.', () => { const G = T.solo(1); G.grim.city = [T.take(G, 'twig_barge')]; const [m] = hand(G, 0, ['miner_mole']); res(G, 0, { berry: 3 }); play(G, 0, m); chL(G, /Copy/); eq(P(G).res.twig, 2); });
R('Solo: anything you must give a rival (Post Office cards, Monk berries) is simply discarded/lost.', () => { const G = T.solo(1); city(G, 0, ['post_office']); hand(G, 0, ['farm', 'mine']); const d0 = G.discard.length; wDest(G, 0, 'post_office'); chL(G, /Give/); chL(G, /Give/); eq(G.discard.length - d0 >= 2, true); });

// ============================================================ RUNNER
if (process.argv.includes('--md')) {
  let cur = '';
  console.log('# Hollowbough rules checklist (W442)\n\nEvery rule below has exactly one assertion block in `logic-test.js` with the same number. Rules marked **N/A** are physical or presentation-only and cannot be tested against the engine. No original rulebook text is stored here; rules are written in our own words.\n');
  for (const r of RULES) { if (r.sec !== cur) { cur = r.sec; console.log('\n## ' + cur + '\n'); } console.log(r.n + '. ' + (r.fn ? '' : '**N/A** ') + r.text); }
  process.exit(0);
}
let pass = 0, fail = 0, na = 0; const failed = [];
for (const r of RULES) {
  if (!r.fn) { na++; continue; }
  try { r.fn(); pass++; } catch (e) { fail++; failed.push(r.n); console.log('FAIL rule ' + r.n + ': ' + (e instanceof Miss ? e.message : 'engine error ' + (e && e.message || e).toString().split('\n')[0]) + '   [' + r.text.slice(0, 70) + ']'); }
}
console.log('rules total ' + RULES.length + ' (N/A ' + na + '), tested ' + (pass + fail) + ', pass ' + pass + ', fail ' + fail);
process.exit(fail ? 1 : 0);
